int __cdecl wrap_pci_get(u32 idx, void *out)
{
    KAPI_HIT(220);
    /* 出力範囲が書けるか (票 TASK_KAPI_OUTPUT_GUARD) */
    if (!ring3_user_ranges_writable((u32)out, KAPI_OUT_LEN(out, PCI_DEV_STRUCT_SIZE),
                                    (u32)0, 0u)) {
        ring3_fault_kill();   /* 戻らない */
    }
    return pci_get(idx, out);
}

